  rewrite ?swrap32_modm, ?swrap32_modl, ?swrap32_modr, ?swrap32_modsl, ?swrap32_modsr;
  rewrite ?to_bv64_mod, ?to_bv64_addmod_l, ?to_bv64_addmod_r, ?to_bv64_submod_l, ?to_bv64_submod_r;
